contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send (must be 10 ether to not revert) and a dummy uint to allow varied inputs.
    function run(uint amount, uint dummy) public payable {
        // ensure this contract holds enough to send the requested amount
        require(address(this).balance >= amount);

        // record before-values
        uint before_balance_c = address(c).balance;
        uint before_past = c.pastBlockTime();

        // perform the call to fallback with the provided amount
        bool reverted;
        // call may revert; catch that and record
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values (allowed public getter and balances)
        uint after_balance_c = address(c).balance;
        uint after_past = c.pastBlockTime();

        // General rule asserted:
        // If the call did not revert, then amount must have been exactly 10 ether,
        // after_past equals current block.timestamp (i.e., strictly greater than before_past),
        // and if block.number % 15 == 0 then contract's balance is 0 (it transferred all balance to caller),
        // otherwise contract's balance increased by exactly 10 ether compared to before.
        // If the call reverted, no guarantees about state changes are required.
        assert(
            reverted || (
                amount == 10 ether
                && after_past == block.timestamp
                && after_past > before_past
                && (
                    (block.number % 15 == 0 && after_balance_c == 0)
                    || (block.number % 15 != 0 && after_balance_c == before_balance_c + 10 ether)
                )
            )
        );
    }

    // allow receiving ether when C sends funds back
    receive() external payable {}
}

