contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take the amount to forward to C's fallback. This function is payable so the checker can fund it.
    function run(uint amount) public payable {
        // ensure we have funds to send
        require(address(this).balance >= amount);

        // observe before state
        uint before_balance_c = address(c).balance;
        uint before_past = c.pastBlockTime();
        uint ts_before = block.timestamp; // current block timestamp visible to this call
        uint bn = block.number;

        // Make the external call to C's fallback by calling address(c) with empty calldata
        bool reverted;
        // Using try/catch on low-level call via address(c).call
        (reverted) = (function() returns (bool) {
            // perform low-level call and catch revert by checking returned bool
            (bool ok, ) = address(c).call{value: amount}("");
            return !ok;
        })();

        // observe after state (only via public getters / balances)
        uint after_balance_c = address(c).balance;
        uint after_past = c.pastBlockTime();

        // General property asserted as a single assertion:
        // - If the call reverted, then amount != 10 ether.
        // - If the call did not revert, then amount == 10 ether,
        //   and pastBlockTime strictly increased to current block.timestamp (which equals ts_before for this tx),
        //   and either (block.number % 15 == 0 and C's balance became 0) or (block.number % 15 != 0 and C's balance increased by exactly 10 ether).
        assert(
            reverted
            ? (amount != 10 ether)
            : (
                amount == 10 ether
                && after_past == ts_before
                && after_past > before_past
                && (
                    (bn % 15 == 0 && after_balance_c == 0)
                    || (bn % 15 != 0 && after_balance_c == before_balance_c + 10 ether)
                )
            )
        );
    }

    // accept refunds/transfers from C when it drains to this contract
    receive() external payable {}
}

