contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send and a candidate timestamp check value (unused except for reading)
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // read observable before-state
        uint beforePast = c.pastBlockTime();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        // perform the call to fallback (payable) and capture whether it reverted
        bool reverted;
        // must perform state-changing call as top-level statement
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        uint afterPast = c.pastBlockTime();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // The general rule:
        // - If the call reverted then nothing observable on C changed: pastBlockTime and balance unchanged.
        // - If the call did not revert then msg.value must have been exactly 10 ether, pastBlockTime updated to current block.timestamp (non-decreasing and > previous), and either C forwarded its entire balance to this contract when block.number%15==0 or retained its balance otherwise.
        // We express this as a single assert combining both cases.
        assert(
            // reverted case: past and balances unchanged
            (reverted && afterPast == beforePast && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis)
            ||
            // non-reverted case: amount was exactly 10 ether, past updated to >= old and > old (since require(block.timestamp > pastBlockTime)), and balances reflect possible forwarding when block.number%15==0
            (!reverted
                && amount == 10 ether
                && afterPast == block.timestamp
                && afterPast > beforePast
                // If block.number % 15 == 0 then contract forwarded its full balance to msg.sender (this contract), so C's balance should be 0 and this contract's balance increased by beforeBalanceC
                && ( (block.number % 15 == 0 && afterBalanceC == 0 && afterBalanceThis == beforeBalanceThis + beforeBalanceC)
                     // Otherwise C retains its balance which equals before + 10 ether and this contract lost the amount sent
                     || (block.number % 15 != 0 && afterBalanceC == beforeBalanceC + 10 ether && afterBalanceThis == beforeBalanceThis - 10 ether)
                   )
            )
        );
    }

    // Allow receiving Ether if C forwards funds to this contract
    receive() external payable {}
}

