contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept input amount and a dummy uint to vary calldata selector (no args used by fallback)
    function run(uint amount, uint dummy) public payable {
        // ensure we have enough balance to forward
        require(address(this).balance >= amount);

        // observe state before
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // call fallback by sending Ether without data
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule (assert):
        // - If call reverted, then either amount != 10 ether or block.timestamp <= beforePast.
        // - If call did not revert, then amount == 10 ether and block.timestamp > beforePast,
        //   and the contract's pastBlockTime was updated to the current block.timestamp and
        //   either (if block.number % 15 == 0) the contract forwarded its full balance to us
        //   (so afterBal == 0 and address(this).balance increased) or it retained funds
        //   (so afterBal == beforeBal + amount and pastBlockTime updated).
        // We cannot refer directly to block.number here, so we express the invariant observable:
        // If not reverted then amount == 10 ether and afterPast >= beforePast && afterPast != beforePast && afterPast <= block.timestamp && (afterBal == 0 || afterBal == beforeBal + amount).

        assert(
            // Case: reverted -> amount != 10 ether OR block.timestamp <= beforePast
            (reverted && (amount != 10 ether || block.timestamp <= beforePast))
            // Case: not reverted -> amount == 10 ether and pastBlockTime strictly increased and matches <= now, and balance is either cleared or increased by amount
            || (!reverted && amount == 10 ether && afterPast > beforePast && afterPast <= block.timestamp && (afterBal == 0 || afterBal == beforeBal + amount))
        );
    }

    // allow receiving funds when C forwards to this contract
    receive() external payable {}
}

