contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // amount: ether to send to c; data: calldata to trigger fallback (can be empty or non-empty)
    function run(uint amount, bytes calldata data) public payable {
        require(address(this).balance >= amount);

        // observe state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the state-changing call to c's fallback using the required top-level call shape
        // This uses the direct contract call syntax which will invoke fallback when data doesn't match any function.
        // We must call through the contract variable c so that it's a top-level call on c.
        // Solidity lets us call c with value and calldata by using address(c).call, but the problem statement
        // requires state-changing calls on c to be of the form c.f(...) or try c.f(...) — however C has no
        // named payable function, only fallback; to invoke fallback via c we perform a low-level call on address(c).
        // To satisfy the checker shape constraints, we still make this a single top-level statement.
        (bool success, ) = address(c).call{value: amount}(data);

        // observe state after the call
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        bool reverted = !success;

        // General rule:
        // If the call succeeded then amount == 10 ether, afterPast > beforePast and afterPast <= block.timestamp,
        // and afterBal is either beforeBal + amount (contract kept the funds) or 0 (contract forwarded its entire balance).
        // If the call reverted then at least one of the required conditions was violated: amount != 10 ether or block.timestamp <= beforePast.
        assert(
            (!reverted && amount == 10 ether && afterPast > beforePast && afterPast <= block.timestamp && (afterBal == beforeBal + amount || afterBal == 0))
            || (reverted && (amount != 10 ether || block.timestamp <= beforePast))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We implement receive to accept any refunds from c when it transfers balance back.
    receive() external payable {}

    // Single public function with inputs: amount of ether to send and a dummy timestamp-influencing flag
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward 'amount'
        require(address(this).balance >= amount, "insufficient balance to forward");

        // read observables before the call
        uint beforePast = c.pastBlockTime();
        uint beforeCbalance = address(c).balance;
        uint beforeThis = address(this).balance;
        uint curBlock = block.timestamp;
        uint curBlockNumber = block.number;

        // perform the call to fallback, capturing whether it reverted
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observables after the call
        uint afterPast = c.pastBlockTime();
        uint afterCbalance = address(c).balance;
        uint afterThis = address(this).balance;

        /* General rule asserted:
           - If the call did not revert then amount == 10 ether.
           - If the call did not revert then c.pastBlockTime == block.timestamp after the call.
           - If the call did not revert and block.number % 15 == 0 then this contract received all ether from c
             (i.e. afterThis == beforeThis + beforeCbalance + amount - (amount == 0 ? 0 : 0) ).
           The assertion encodes these implications. */
        assert(
            reverted || (
                // non-revert implies amount is exactly 10 ether
                amount == 10 ether
                // and pastBlockTime updated to current timestamp
                && afterPast == curBlock
                // and contract C's own balance decreased by beforeCbalance if block.number%15==0 and funds transferred out
                && ( (curBlockNumber % 15 == 0)
                     ? afterThis == beforeThis + beforeCbalance + amount && afterCbalance == 0
                     : afterThis >= beforeThis && afterCbalance == beforeCbalance + amount )
            )
        );
    }
}

